window.__finlexDocLoaded(10153,{"id":10153,"articles":[{"id":1000654,"no":"Overview","heading":"Scope & 2023 Responsible Business Conduct Update","text":"Adopted by adhering governments representing the major global economies, the OECD Guidelines for Multinational Enterprises on Responsible Business Conduct provide non-binding principles and standards for responsible conduct in a global context. The June 2023 update strengthens expectations on climate transition, biodiversity, digital technology, downstream value-chain due diligence, and anti-corruption.","seq":0},{"id":1000655,"no":"6-Step Due Diligence & Chapters","heading":"Risk-Based Due Diligence, Core Chapters & National Contact Points","text":"[6-Step Risk-Based Due Diligence Process]\n• 1. Embed RBC into policies and management systems.\n• 2. Identify and assess actual and potential adverse impacts in operations, supply chains, and business relationships.\n• 3. Cease, prevent, or mitigate adverse impacts.\n• 4. Track implementation and results.\n• 5. Communicate how impacts are addressed.\n• 6. Provide for or cooperate in remediation when appropriate.\n\n[Core Thematic Chapters]\n• Disclosure (Ch. III): Transparent reporting on financial, governance, and sustainability impacts.\n• Human Rights & Employment (Ch. IV–V): Alignment with UN Guiding Principles on Business and Human Rights.\n• Environment (Ch. VI): Science-based climate targets, Scope 1–3 emissions, biodiversity, and circular economy.\n• Combating Bribery & Solicitation (Ch. VII), Consumer Interests (Ch. VIII), Science/Technology/Innovation (Ch. IX), Competition (Ch. X), and Taxation (Ch. XI — complying with both the letter and spirit of tax laws, cooperating with tax authorities, and applying arm's length pricing).\n• National Contact Points (NCPs): Government-established non-judicial grievance and mediation bodies handling specific instances alleging non-observance of the Guidelines.","seq":1},{"id":1000656,"no":"Official Access","heading":"Official Publication & RBC Topic Hub","text":"Official Publication Page: https://www.oecd.org/en/publications/oecd-guidelines-for-multinational-enterprises-on-responsible-business-conduct_81f92357-en.html\nOECD Responsible Business Conduct Hub: https://www.oecd.org/en/topics/responsible-business-conduct.html\nStatus: in_force (2023 Edition).","seq":2}]});
